static std::string ProjFromTitle() {
    if (!g_osHwnd) return {};
    char buf[512] = {}; GetWindowTextA(g_osHwnd, buf, sizeof(buf));
    std::string t(buf);
    auto p = t.rfind(" - Outfit Studio");
    if (p == std::string::npos) return {};
    std::string n = t.substr(0, p);
    if (!n.empty() && n.back() == '*') n.pop_back();
    return n;
}

